    @Transactional
    open fun createRiskAssessment(@Valid @Body request: CreateRiskAssessmentRequest, authentication: Authentication): HttpResponse<*> {
        if (!riskAssessmentAccessService.isGlobal(authentication)) return HttpResponse.status<Any>(HttpStatus.FORBIDDEN)
        if (!authentication.roles.contains("ADMIN") && listOfNotNull(request.assessorRef, request.respondentRef).any {
            it.id == null && !it.email.isNullOrBlank() && userRepository.findByEmailIgnoreCase(it.email!!.trim()).isEmpty
        }) return HttpResponse.status<Any>(HttpStatus.FORBIDDEN)
        return try {
            // Validate request
            val validationError = request.validate()
            if (validationError != null) {
                return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR", validationError))
            }

            val basisType = request.getBasisType()
            val suppliedBasis = request.demandId ?: request.assetId ?: request.awsAccountId

            log.debug("Creating risk assessment with basis type: {} and identifier: {}", basisType, suppliedBasis)

            // 1. PRE-VALIDATE BASIS first so a missing basis doesn't orphan a lazy-created User row
            // SECURITY (A01): basisId is caller-supplied. For an ASSET basis it names an asset
            // directly; for a DEMAND basis, a CHANGE demand's existingAsset is echoed back in the
            // response (title/description/asset name) once the assessment is created. Both must be
            // resolved through the unified asset-access boundary — never a bare findById() whose
            // result is returned — matching the fix already applied to DemandController.
            val resolvedBasis: Any? = when (basisType) {
                AssessmentBasisType.DEMAND -> {
                    val basisId = request.demandId!!
                    val demand = demandRepository.findById(basisId).orElse(null)
                        ?: return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR", "Demand not found"))
                    if (demand.status != DemandStatus.APPROVED) {
                        return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR",
                            "Only approved demands can have risk assessments created"))
                    }
                    val existingAssetId = demand.existingAsset?.id
                    if (existingAssetId != null && !assetFilterService.canAccessAsset(existingAssetId, authentication)) {
                        return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR", "Demand not found"))
                    }
                    demand
                }
                AssessmentBasisType.ASSET -> {
                    val basisId = request.assetId!!
                    if (!assetFilterService.canAccessAsset(basisId, authentication)) {
                        return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR", "Asset not found"))
                    }
                    assetRepository.findById(basisId).orElse(null)
                        ?: return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR", "Asset not found"))
                }
                AssessmentBasisType.AWS_ACCOUNT -> {
                    if (authentication.roles.none { it == "ADMIN" || it == "SECCHAMPION" }) {
                        return HttpResponse.status<ErrorResponse>(HttpStatus.FORBIDDEN)
                            .body(ErrorResponse("FORBIDDEN", "ADMIN or SECCHAMPION role required for AWS account assessments"))
                    }
                    awsAccountRepository.findByAwsAccountId(request.awsAccountId!!).orElse(null)
                }
            }

            // 2. Resolve assessor (basis is known to exist — no orphan risk)
            val assessor = try {
                userResolutionService.resolveByIdOrEmail(
                    userId = request.assessorRef?.id ?: request.assessorId,
                    email = request.assessorRef?.email,
                    context = "risk assessment assessor"
                )
            } catch (e: NoSuchElementException) {
                return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR", "Assessor not found"))
            } catch (e: IllegalArgumentException) {
                return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR", e.message ?: "Invalid assessor"))
            }

            // Get requestor from current session (would need security context in real implementation)
            // For now, assuming assessor is also requestor
            val requestor = assessor

            // 3. Resolve respondent if provided
            val respondent: User? = if (request.respondentRef != null || request.respondentId != null) {
                try {
                    userResolutionService.resolveByIdOrEmail(
                        userId = request.respondentRef?.id ?: request.respondentId,
                        email = request.respondentRef?.email,
                        context = "risk assessment respondent"
                    )
                } catch (e: NoSuchElementException) {
                    return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR", "Respondent not found"))
                } catch (e: IllegalArgumentException) {
                    return HttpResponse.badRequest(ErrorResponse("VALIDATION_ERROR", e.message ?: "Invalid respondent"))
                }
            } else null

            // 4. Build risk assessment from pre-validated basis
            val riskAssessment = when (basisType) {
                AssessmentBasisType.DEMAND -> {
                    @Suppress("UNCHECKED_CAST")
                    val demand = resolvedBasis as com.secman.domain.Demand

                    // Create demand-based risk assessment with proper fields
                    val assessment = RiskAssessment(
                        startDate = request.startDate ?: LocalDate.now(),
                        endDate = request.endDate,
                        assessmentBasisType = AssessmentBasisType.DEMAND,
                        assessmentBasisId = request.demandId!!,
                        assessor = assessor,
                        requestor = requestor,
                        demand = demand // Keep for backward compatibility
                    )

                    // Update demand status to IN_PROGRESS
                    demand.status = DemandStatus.IN_PROGRESS
                    demandRepository.update(demand)

                    assessment
                }
                AssessmentBasisType.ASSET -> {
                    @Suppress("UNCHECKED_CAST")
                    val asset = resolvedBasis as com.secman.domain.Asset

                    // Create asset-based risk assessment with proper fields
                    RiskAssessment(
                        startDate = request.startDate ?: LocalDate.now(),
                        endDate = request.endDate,
                        assessmentBasisType = AssessmentBasisType.ASSET,
                        assessmentBasisId = request.assetId!!,
                        assessor = assessor,
                        requestor = requestor,
                        asset = asset // Keep for backward compatibility
                    )
                }
                AssessmentBasisType.AWS_ACCOUNT -> {
                    val account = (resolvedBasis as? AwsAccount) ?: try {
                        awsAccountRepository.save(
                            AwsAccount(awsAccountId = request.awsAccountId!!, updatedBy = authentication.name)
                        )
                    } catch (e: Exception) {
                        awsAccountRepository.findByAwsAccountId(request.awsAccountId!!).orElseThrow { e }
                    }
                    RiskAssessment(
                        startDate = request.startDate ?: LocalDate.now(),
                        endDate = request.endDate,
                        assessmentBasisType = AssessmentBasisType.AWS_ACCOUNT,
                        assessmentBasisId = account.id!!,
                        assessor = assessor,
                        requestor = requestor,
                        awsAccount = account
                    )
                }
            }

            // Set common fields
            riskAssessment.respondent = respondent
            riskAssessment.notes = request.notes?.trim()?.takeIf { it.isNotBlank() }

            // Handle use case associations
            request.useCaseIds?.let { ids ->
                val useCases = ids.mapNotNull { useCaseId ->
                    useCaseRepository.findById(useCaseId).orElse(null)
                }.toMutableSet()
                riskAssessment.useCases = useCases
                log.debug("Associated {} use cases with risk assessment", useCases.size)
            }

            val savedAssessment = riskAssessmentRepository.save(riskAssessment)
            workflow.initialize(savedAssessment)

            // Flush to ensure the entity is persisted with an ID
            entityManager.flush()

            // Force loading of related entities for response
            entityManager.refresh(savedAssessment)
            when (basisType) {
                AssessmentBasisType.DEMAND -> {
                    @Suppress("DEPRECATION")
                    savedAssessment.demand?.title
                    @Suppress("DEPRECATION")
                    savedAssessment.demand?.existingAsset?.name
                }
                AssessmentBasisType.ASSET -> {
                    @Suppress("DEPRECATION")
                    savedAssessment.asset?.name
                }
                AssessmentBasisType.AWS_ACCOUNT -> savedAssessment.awsAccount?.awsAccountId
            }
            savedAssessment.assessor.username
            savedAssessment.requestor.username
            savedAssessment.respondent?.username
            savedAssessment.useCases.size

            // Publish RiskAssessmentCreatedEvent for email notifications
            try {
                // Only publish event if we have a valid saved assessment with ID
                if (savedAssessment.id != null) {
                    val event = createRiskAssessmentEvent(savedAssessment)
                    eventPublisher.publishEvent(event)
                    log.debug("Published RiskAssessmentCreatedEvent for assessment: {}", savedAssessment.id)
                } else {
                    log.warn("Cannot publish RiskAssessmentCreatedEvent - assessment ID is null")
                }
package com.secman.service

import com.secman.domain.AccountOnboardingMode
import com.secman.dto.BulkUserMappingRequest
import com.secman.dto.BulkUserMappingResponse
import com.secman.dto.WorkgroupAccountLinkSummary
import com.secman.util.EmailAddressValidator
import jakarta.inject.Singleton
import org.slf4j.LoggerFactory

/**
 * The one implementation of "bulk import user mappings, then do the post-commit work".
 *
 * Both entry points use it, so they can never drift:
 * - REST  `POST /api/user-mappings/bulk` ([com.secman.controller.UserMappingController])
 * - MCP   `import_user_mappings` ([com.secman.mcp.tools.ImportUserMappingsTool])
 *
 * Ordering is load-bearing. The operator notification and the risk assessments run
 * only AFTER [UserMappingService.bulkCreateMappings] has committed, so a slow or
 * failing email — or a failure while starting an assessment — can never roll back
 * mappings that were already persisted.
 */
@Singleton
open class UserMappingBulkImportService(
    private val userMappingService: UserMappingService,
    private val newAccountNotificationService: NewAccountNotificationService,
    private val accountOnboardingService: AccountOnboardingService,
    private val importCompletionNotifier: ImportCompletionNotifier,
    private val workgroupAccountLinkService: WorkgroupAccountLinkService
) {
    private val logger = LoggerFactory.getLogger(UserMappingBulkImportService::class.java)

    /**
     * Fail-fast validation of the request's side-effect options. Returns a
     * human-readable message (HTTP 400 / MCP `VALIDATION_ERROR`), or null when valid.
     *
     * Deliberately runs before any import so an operator with a bad notify address,
     * an unknown use case, or no ACTIVE requirements release is told about it
     * instead of getting a half-done import.
     */
    open fun validate(request: BulkUserMappingRequest): String? {
        if (request.notifyNewAccounts) {
            // notifyAddress is handed to InternetAddress.parse, where a comma would silently
            // split one recipient into two and a CR/LF would reach a mail header. One shared
            // boundary check — see EmailAddressValidator for what it rejects and why.
            if (!EmailAddressValidator.isValidRecipient(request.notifyAddress)) {
                return "notifyAddress must be a valid email when notifyNewAccounts is true"
            }
        }
        // Reject the one combination that cannot be honoured rather than guessing which half
        // the caller meant.
        AccountOnboardingMode.validateCompatibility(request.onboardingMode, request.startRiskAssessment)
            ?.let { return it }

        // planFrom returns null only when neither the mode nor the legacy flag was set, which
        // is an ordinary import with no side effects to validate.
        val plan = accountOnboardingService.planFrom(
            explicitMode = request.onboardingMode,
            startRiskAssessment = request.startRiskAssessment,
            sendWelcomeEmail = request.sendWelcomeEmail,
            useCaseName = request.riskAssessmentUseCase,
            deadlineDays = request.riskAssessmentDeadlineDays,
            expiryDays = request.questionnaireExpiryDays
        ) ?: return null

        return accountOnboardingService.validateRequest(plan)
    }

    /**
     * Import the mappings, then run the post-commit side effects.
     *
     * @param requestorUserId the ADMIN who triggered the import; becomes the
     *        requestor of any risk assessment started here.
     */
    open fun execute(
        request: BulkUserMappingRequest,
        requestorUserId: Long?,
        source: String = "Bulk import"
    ): BulkUserMappingResponse {
        val result = userMappingService.bulkCreateMappings(request)

        // Link every account whose entry carried a display name to the workgroup named
        // after it (`aws-<display_name>`), creating that workgroup when it is missing.
        // AFTER the import committed, like every other side effect below: a workgroup
        // that cannot be created must not roll back mappings that already persisted.
        val workgroupLinks = linkWorkgroups(request, requestorUserId)

        // Send the operator email AFTER the transaction has committed, so a
        // slow/failed send never rolls back the persisted mappings.
        var finalResult = if (request.notifyNewAccounts && !request.dryRun && result.newAccounts.isNotEmpty()) {
            val recipient = request.notifyAddress!!.trim()
            val sent = newAccountNotificationService.sendImportNotification(recipient, result.newAccounts)
            result.copy(
                notificationRecipient = recipient,
                notificationSent = sent,
                notificationError = if (sent) null else "Email send failed (check email configuration / logs)"
            )
        } else {
            result
        }
        finalResult = finalResult.copy(workgroupLinks = workgroupLinks)

        // Onboard the owners of brand-new AWS accounts — welcome mail, and depending on the
        // mode an immediate assessment or a questionnaire invite. Also AFTER the import
        // committed so a failure here never rolls back the persisted mappings.
        //
        // Unlike the two side effects above this runs on a dry run too: it persists and sends
        // nothing, but reports what it *would* do, which is the point of asking for a preview.
        val plan = accountOnboardingService.planFrom(
            explicitMode = request.onboardingMode,
            startRiskAssessment = request.startRiskAssessment,
            sendWelcomeEmail = request.sendWelcomeEmail,
            useCaseName = request.riskAssessmentUseCase,
            deadlineDays = request.riskAssessmentDeadlineDays,
            expiryDays = request.questionnaireExpiryDays
        )
        if (plan != null && result.newAccounts.isNotEmpty()) {
            val outcome = accountOnboardingService.onboardNewAccounts(
                newAccounts = result.newAccounts,
                plan = plan,
                requestorUserId = requestorUserId,
                dryRun = request.dryRun
            )
            finalResult = finalResult.copy(
                riskAssessments = outcome.riskAssessments,
                onboarding = outcome.onboarding
            )
        }

        logger.info(
            "Bulk import complete: processed={}, created={}, pending={}, skipped={}, newAccounts={}, " +
                "assessments={}, onboarded={}, workgroupsCreated={}, accountsLinked={}",
            finalResult.totalProcessed, finalResult.created, finalResult.createdPending,
            finalResult.skipped, finalResult.newAccounts.size, finalResult.riskAssessments.size,
