@Secured("ADMIN", "SECCHAMPION")
class AccountOnboardingSettingsController(
    private val settings: AccountOnboardingSettingsService,
    private val audit: AuditLogService
) {
    @Get
    @Secured("ADMIN", "SECCHAMPION")
    fun get() = settings.get()

